function validate([nums, target]) {
  if (!Array.isArray(nums) || !Array.isArray(target)) return 'nums and target must be arrays.';
  if (nums.length !== target.length) return 'nums and target need the same length.';
  if (nums.length < 1 || nums.length > 100000) return 'The arrays need 1 to 10^5 values.';
  if ([...nums, ...target].some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Every value is an integer from 1 to 10^6.';
  const odds = list => list.filter(v => v % 2 === 1).length;
  const total = list => list.reduce((sum, v) => sum + v, 0);
  if (odds(nums) !== odds(target)) return 'Moves keep each value odd or even, so both arrays need the same number of odd values.';
  if (total(nums) !== total(target)) return 'Moves keep the total, so both arrays need the same sum.';
  return null;
}

