function makeSimilar(nums, target) {
  // Try every way to give each value of nums a partner of the same parity in target.
  // With partners fixed, each move raises one value by 2, so it takes (sum of upward gaps) / 2 moves.
  const n = nums.length;
  const used = new Array(n).fill(false);
  let best = Infinity;
  const assign = (i, upward) => {
    if (i === n) { best = Math.min(best, upward / 2); return; }
    for (let j = 0; j < n; j++) {
      if (used[j] || Math.abs(nums[i] - target[j]) % 2 === 1) continue;
      used[j] = true;
      assign(i + 1, upward + Math.max(0, target[j] - nums[i]));
      used[j] = false;
    }
  };
  assign(0, 0);
  return best;
}

