function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 5);
  const high = size === 'large' ? 1000000 : 40;
  const target = Array.from({ length: n }, () => 1 + Math.floor(rand() * high));
  const nums = target.slice();
  // Shifting 2s between positions keeps every parity and the total, so nums can always reach target.
  const rounds = n < 2 ? 0 : size === 'large' ? 4000 : Math.floor(rand() * 5);
  for (let r = 0; r < rounds; r++) {
    const i = Math.floor(rand() * n);
    const j = Math.floor(rand() * n);
    if (i === j) continue;
    const room = Math.min(Math.floor((high - nums[i]) / 2), Math.floor((nums[j] - 1) / 2));
    const steps = Math.floor(rand() * (Math.min(room, size === 'large' ? room : 3) + 1));
    nums[i] += 2 * steps;
    nums[j] -= 2 * steps;
  }
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, target];
}
